// Theme stylesheets, one file per axis.
//
// A theme used to be a single `.theme.css` that carried both the chrome and the
// Markdown palette, so the two could only move together. They are now split:
// `ui/<id>.css` styles the chrome, `md/<id>.css` styles the body, and both are
// lazy: `import.meta.glob` leaves every file behind its own dynamic import, so
// a session downloads the two themes it actually displays.
//
// `manifest.json` is generated by `scripts/themes/build.mjs` and is the only
// list the UI needs: id, label, appearance and the Prism theme to pair with.

import manifest from '../assets/themes/manifest.json'

export interface ThemeEntry {
  id: string
  label: string
  appearance: 'light' | 'dark'
  prism: string | null
}

export const THEMES: ThemeEntry[] = manifest as ThemeEntry[]

type CssLoader = () => Promise<string>

const uiCss = import.meta.glob('../assets/themes/ui/*.css', {
  query: '?inline',
  import: 'default'
}) as Record<string, CssLoader>

const mdCss = import.meta.glob('../assets/themes/md/*.css', {
  query: '?inline',
  import: 'default'
}) as Record<string, CssLoader>

const prismCss = import.meta.glob('../assets/themes/prismjs/*.theme.css', {
  query: '?inline',
  import: 'default'
}) as Record<string, CssLoader>

export const getTheme = (id: string): ThemeEntry | undefined => THEMES.find(theme => theme.id === id)

const load = async(loaders: Record<string, CssLoader>, path: string): Promise<string> => {
  const loader = loaders[path]
  if (!loader) {
    console.error(`[theme] no stylesheet for ${path}`)
    return ''
  }
  return loader()
}

export const loadUiCss = (id: string): Promise<string> => load(uiCss, `../assets/themes/ui/${id}.css`)

export const loadMdCss = (id: string): Promise<string> => load(mdCss, `../assets/themes/md/${id}.css`)

/** Syntax highlighting follows the Markdown theme, never the chrome one. */
export const loadPrismCss = async(id: string): Promise<string> => {
  const prism = getTheme(id)?.prism
  if (!prism) return ''
  return load(prismCss, `../assets/themes/prismjs/${prism}.theme.css`)
}
